#include <iostream>

int main()
{
    std::cout << "Enter year, lottery number, and guess: ";
    int year = 0;
    int lottery = 0;
    int guess = 0;
    if (!(std::cin >> year >> lottery >> guess)) {
        return 0;
    }

    bool isLeapYear = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    if (isLeapYear) {
        std::cout << year << " is a leap year" << std::endl;
    } else {
        std::cout << year << " is not a leap year" << std::endl;
    }

    int lotteryDigit1 = lottery / 10;
    int lotteryDigit2 = lottery % 10;
    int guessDigit1 = guess / 10;
    int guessDigit2 = guess % 10;

    std::cout << "The lottery number is " << lottery << std::endl;

    if (guess == lottery) {
        std::cout << "Exact match: you win $10,000" << std::endl;
    } else if (guessDigit2 == lotteryDigit1 && guessDigit1 == lotteryDigit2) {
        std::cout << "Match all digits: you win $3,000" << std::endl;
    } else if (guessDigit1 == lotteryDigit1 || guessDigit1 == lotteryDigit2 ||
               guessDigit2 == lotteryDigit1 || guessDigit2 == lotteryDigit2) {
        std::cout << "Match one digit: you win $1,000" << std::endl;
    } else {
        std::cout << "Sorry, no match" << std::endl;
    }

    return 0;
}

#include <iostream>

int main()
{
    std::cout << "Enter filing status (0-Single, 1-Joint, 2-Separate, 3-Head): ";
    int status = 0;
    if (!(std::cin >> status)) {
        return 0;
    }

    switch (status)
    {
        case 0:
            std::cout << "Compute tax for single filers" << std::endl;
            break;
        case 1:
            std::cout << "Compute tax for married jointly or qualifying widow(er)" << std::endl;
            break;
        case 2:
            std::cout << "Compute tax for married filing separately" << std::endl;
            break;
        case 3:
            std::cout << "Compute tax for head of household" << std::endl;
            break;
        default:
            std::cout << "Error: invalid status" << std::endl;
            break;
    }

    return 0;
}
